CREATE TABLE public.evidence_refs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id text NOT NULL REFERENCES public.cases(id) ON DELETE RESTRICT,incident_id uuid REFERENCES public.incidents(id) ON DELETE RESTRICT,source_id text NOT NULL REFERENCES public.sources(id) CHECK(source_id<>'cloud'),record_id text NOT NULL CHECK(record_id ~ '^(finding|comment|profile|artifact)\..+$'),record_code text,platform text,item_type text,published_at timestamptz,files jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(files)='array'),note text,linked_by uuid DEFAULT auth.uid(),linked_by_name text,linked_at timestamptz NOT NULL DEFAULT now(),UNIQUE(case_id,source_id,record_id)); GRANT SELECT,INSERT ON public.evidence_refs TO authenticated; GRANT ALL ON public.evidence_refs TO service_role; ALTER TABLE public.evidence_refs ENABLE ROW LEVEL SECURITY; CREATE POLICY refs_read ON public.evidence_refs FOR SELECT TO authenticated USING(public.is_investigator(auth.uid()) AND public.can_access_case(auth.uid(),case_id)); CREATE POLICY refs_add ON public.evidence_refs FOR INSERT TO authenticated WITH CHECK(public.is_investigator(auth.uid()) AND public.can_access_case(auth.uid(),case_id) AND linked_by=auth.uid()); CREATE TRIGGER refs_immutable BEFORE UPDATE OR DELETE ON public.evidence_refs FOR EACH ROW EXECUTE FUNCTION public.block_mutation();
ALTER TABLE public.custody_events ADD COLUMN source_id text NOT NULL DEFAULT 'cloud' REFERENCES public.sources(id),ADD COLUMN evidence_ref_id uuid REFERENCES public.evidence_refs(id) ON DELETE RESTRICT; ALTER TABLE public.custody_events DROP CONSTRAINT IF EXISTS custody_events_action_check; ALTER TABLE public.custody_events ADD CONSTRAINT custody_events_action_check CHECK(action IN ('captured','accessed','transferred','exported','re-hashed','linked')); ALTER TABLE public.custody_events ADD CONSTRAINT custody_home_reference CHECK(source_id='cloud' OR evidence_ref_id IS NOT NULL) NOT VALID;
CREATE TABLE public.clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code ~ '^[A-Z0-9][A-Z0-9-]{1,23}$'),name text NOT NULL,legal_name text,sector text,contact_name text,contact_email text,notes text,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),portal_enabled boolean NOT NULL DEFAULT false CHECK(portal_enabled=false),created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.clients TO authenticated; GRANT ALL ON public.clients TO service_role; ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY; CREATE POLICY clients_read ON public.clients FOR SELECT TO authenticated USING(public.is_investigator(auth.uid())); CREATE POLICY clients_add ON public.clients FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'owner')); CREATE POLICY clients_edit ON public.clients FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner')); CREATE TRIGGER clients_touch BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE RESTRICT,code text NOT NULL UNIQUE DEFAULT '',name text NOT NULL,summary text,status text NOT NULL DEFAULT 'scoping' CHECK(status IN ('scoping','active','paused','delivered','closed')),opened_on date NOT NULL DEFAULT current_date,due_on date,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role; ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_members(project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,role text NOT NULL CHECK(role IN ('lead','analyst','reviewer','client_viewer')),PRIMARY KEY(project_id,user_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_members TO authenticated; GRANT ALL ON public.project_members TO service_role; ALTER TABLE public.project_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_briefs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,version integer NOT NULL DEFAULT 1,question text NOT NULL,background text,scope text,out_of_scope text,period_from date,period_to date,platforms text[] NOT NULL DEFAULT '{}',audience text,output_kinds text[] NOT NULL DEFAULT '{}' CHECK(output_kinds <@ ARRAY['evidence_bundle','report','dashboard','dataset']::text[]),constraints text,change_note text NOT NULL CHECK(length(trim(change_note))>0),authored_by uuid NOT NULL DEFAULT auth.uid(),authored_by_name text,authored_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version),UNIQUE(id,project_id)); GRANT SELECT,INSERT ON public.project_briefs TO authenticated; GRANT ALL ON public.project_briefs TO service_role; ALTER TABLE public.project_briefs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_criteria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brief_id uuid NOT NULL,project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,position integer NOT NULL DEFAULT 0,kind text NOT NULL CHECK(kind IN ('inclusion','exclusion','assessment','threshold')),label text NOT NULL,description text,required boolean NOT NULL DEFAULT false,weight numeric NOT NULL DEFAULT 1,FOREIGN KEY(brief_id,project_id) REFERENCES public.project_briefs(id,project_id) ON DELETE RESTRICT,UNIQUE(id,project_id)); GRANT SELECT,INSERT ON public.project_criteria TO authenticated; GRANT ALL ON public.project_criteria TO service_role; ALTER TABLE public.project_criteria ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_cases(project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,case_id text NOT NULL REFERENCES public.cases(id) ON DELETE RESTRICT,PRIMARY KEY(project_id,case_id)); GRANT SELECT,INSERT,DELETE ON public.project_cases TO authenticated; GRANT ALL ON public.project_cases TO service_role; ALTER TABLE public.project_cases ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,item_kind text NOT NULL CHECK(item_kind IN ('cloud_item','home_ref')),item_id uuid REFERENCES public.items(id) ON DELETE RESTRICT,evidence_ref_id uuid REFERENCES public.evidence_refs(id) ON DELETE RESTRICT,CHECK((item_kind='cloud_item' AND item_id IS NOT NULL AND evidence_ref_id IS NULL) OR (item_kind='home_ref' AND evidence_ref_id IS NOT NULL AND item_id IS NULL)),UNIQUE(project_id,item_id),UNIQUE(project_id,evidence_ref_id),UNIQUE(id,project_id)); GRANT SELECT,INSERT,DELETE ON public.project_items TO authenticated; GRANT ALL ON public.project_items TO service_role; ALTER TABLE public.project_items ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,project_item_id uuid NOT NULL,criterion_id uuid NOT NULL,result text NOT NULL CHECK(result IN ('meets','does_not_meet','unclear','not_applicable')),note text,assessed_by uuid NOT NULL DEFAULT auth.uid(),assessed_by_name text,assessed_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_item_id,project_id) REFERENCES public.project_items(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(criterion_id,project_id) REFERENCES public.project_criteria(id,project_id) ON DELETE RESTRICT); GRANT SELECT,INSERT ON public.project_assessments TO authenticated; GRANT ALL ON public.project_assessments TO service_role; ALTER TABLE public.project_assessments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_outputs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,brief_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('evidence_bundle','report','dashboard','dataset')),title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','delivered','withdrawn')),params jsonb NOT NULL DEFAULT '{}',item_count integer NOT NULL DEFAULT 0 CHECK(item_count>=0),file_name text,size_bytes bigint CHECK(size_bytes>=0),sha256 text CHECK(sha256 ~ '^[a-fA-F0-9]{64}$'),location text,shared_with_client boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),created_by_name text,created_at timestamptz NOT NULL DEFAULT now(),approved_by uuid,approved_at timestamptz,delivered_at timestamptz,FOREIGN KEY(brief_id,project_id) REFERENCES public.project_briefs(id,project_id) ON DELETE RESTRICT); GRANT SELECT,INSERT,UPDATE ON public.project_outputs TO authenticated; GRANT ALL ON public.project_outputs TO service_role; ALTER TABLE public.project_outputs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,event text NOT NULL CHECK(event IN ('created','updated','member_added','member_removed','brief_versioned','case_linked','case_unlinked','item_linked','item_unlinked','assessed','output_created','output_status','output_shared','output_unshared','output_downloaded')),actor_id uuid DEFAULT auth.uid(),actor_name text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.project_events TO authenticated; GRANT ALL ON public.project_events TO service_role; ALTER TABLE public.project_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.project_role(_user_id uuid,_project_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.project_members WHERE user_id=_user_id AND project_id=_project_id $$;
CREATE FUNCTION public.can_access_project(_user_id uuid,_project_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_investigator(_user_id) AND (public.has_role(_user_id,'owner') OR coalesce(public.project_role(_user_id,_project_id) IN ('lead','analyst','reviewer'),false)) $$;
CREATE FUNCTION public.can_manage_project(_user_id uuid,_project_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_investigator(_user_id) AND (public.has_role(_user_id,'owner') OR coalesce(public.project_role(_user_id,_project_id)='lead',false)) $$;
CREATE FUNCTION public.can_work_project(_user_id uuid,_project_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_investigator(_user_id) AND (public.has_role(_user_id,'owner') OR coalesce(public.project_role(_user_id,_project_id) IN ('lead','analyst'),false)) $$;
CREATE FUNCTION public.can_view_project_as_client(_user_id uuid,_project_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.is_investigator(_user_id) AND coalesce(public.project_role(_user_id,_project_id)='client_viewer',false) AND EXISTS(SELECT 1 FROM public.projects p JOIN public.clients c ON c.id=p.client_id WHERE p.id=_project_id AND c.portal_enabled) $$;
CREATE OR REPLACE FUNCTION public.can_access_case(_user_id uuid,_case_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND _case_id IS NOT NULL AND (public.has_role(_user_id,'owner') OR EXISTS(SELECT 1 FROM public.case_assignments WHERE case_id=_case_id AND user_id=_user_id) OR (public.is_investigator(_user_id) AND EXISTS(SELECT 1 FROM public.project_cases pc JOIN public.project_members pm ON pm.project_id=pc.project_id WHERE pc.case_id=_case_id AND pm.user_id=_user_id AND pm.role IN ('lead','analyst','reviewer')))) $$;
CREATE FUNCTION public.project_item_case(_item_id uuid,_ref_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT case_id FROM public.evidence_refs WHERE id=_ref_id UNION ALL SELECT inc.case_id FROM public.items i JOIN public.accounts a ON a.id=i.account_id JOIN public.incidents inc ON inc.id=a.incident_uuid WHERE i.id=_item_id LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.project_role(uuid,uuid),public.can_access_project(uuid,uuid),public.can_manage_project(uuid,uuid),public.can_work_project(uuid,uuid),public.can_view_project_as_client(uuid,uuid),public.project_item_case(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.project_role(uuid,uuid),public.can_access_project(uuid,uuid),public.can_manage_project(uuid,uuid),public.can_work_project(uuid,uuid),public.can_view_project_as_client(uuid,uuid),public.project_item_case(uuid,uuid) TO authenticated,service_role;
CREATE POLICY projects_read ON public.projects FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),id) OR public.can_view_project_as_client(auth.uid(),id)); CREATE POLICY projects_add ON public.projects FOR INSERT TO authenticated WITH CHECK(public.is_investigator(auth.uid()) AND created_by=auth.uid()); CREATE POLICY projects_edit ON public.projects FOR UPDATE TO authenticated USING(public.can_manage_project(auth.uid(),id)) WITH CHECK(public.can_manage_project(auth.uid(),id));
CREATE POLICY members_read ON public.project_members FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id)); CREATE POLICY members_write ON public.project_members FOR ALL TO authenticated USING(public.can_manage_project(auth.uid(),project_id)) WITH CHECK(public.can_manage_project(auth.uid(),project_id));
CREATE POLICY briefs_read ON public.project_briefs FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id) OR public.can_view_project_as_client(auth.uid(),project_id)); CREATE POLICY briefs_add ON public.project_briefs FOR INSERT TO authenticated WITH CHECK(public.can_manage_project(auth.uid(),project_id) AND authored_by=auth.uid()); CREATE POLICY criteria_read ON public.project_criteria FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id) OR public.can_view_project_as_client(auth.uid(),project_id)); CREATE POLICY criteria_add ON public.project_criteria FOR INSERT TO authenticated WITH CHECK(public.can_manage_project(auth.uid(),project_id));
CREATE POLICY pc_read ON public.project_cases FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id)); CREATE POLICY pc_add ON public.project_cases FOR INSERT TO authenticated WITH CHECK(public.can_work_project(auth.uid(),project_id) AND public.can_access_case(auth.uid(),case_id)); CREATE POLICY pc_remove ON public.project_cases FOR DELETE TO authenticated USING(public.can_manage_project(auth.uid(),project_id)); CREATE POLICY pi_read ON public.project_items FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id)); CREATE POLICY pi_add ON public.project_items FOR INSERT TO authenticated WITH CHECK(public.can_work_project(auth.uid(),project_id) AND public.can_access_case(auth.uid(),public.project_item_case(item_id,evidence_ref_id))); CREATE POLICY pi_remove ON public.project_items FOR DELETE TO authenticated USING(public.can_manage_project(auth.uid(),project_id));
CREATE POLICY assessment_read ON public.project_assessments FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id)); CREATE POLICY assessment_add ON public.project_assessments FOR INSERT TO authenticated WITH CHECK(public.can_work_project(auth.uid(),project_id) AND assessed_by=auth.uid()); CREATE POLICY output_read ON public.project_outputs FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id) OR (public.can_view_project_as_client(auth.uid(),project_id) AND status='delivered' AND shared_with_client)); CREATE POLICY output_add ON public.project_outputs FOR INSERT TO authenticated WITH CHECK(public.can_work_project(auth.uid(),project_id) AND created_by=auth.uid()); CREATE POLICY output_edit ON public.project_outputs FOR UPDATE TO authenticated USING(public.can_work_project(auth.uid(),project_id)) WITH CHECK(public.can_work_project(auth.uid(),project_id)); CREATE POLICY event_read ON public.project_events FOR SELECT TO authenticated USING(public.can_access_project(auth.uid(),project_id)); CREATE POLICY event_download ON public.project_events FOR INSERT TO authenticated WITH CHECK(event='output_downloaded' AND actor_id=auth.uid() AND public.can_access_project(auth.uid(),project_id));
CREATE VIEW public.project_current_briefs WITH(security_invoker=true) AS SELECT DISTINCT ON(project_id) * FROM public.project_briefs ORDER BY project_id,version DESC; GRANT SELECT ON public.project_current_briefs TO authenticated,service_role;
CREATE INDEX refs_case_idx ON public.evidence_refs(case_id); CREATE INDEX members_user_idx ON public.project_members(user_id); CREATE INDEX briefs_project_idx ON public.project_briefs(project_id,version DESC); CREATE INDEX assessments_latest_idx ON public.project_assessments(project_item_id,criterion_id,assessed_at DESC); CREATE INDEX events_project_idx ON public.project_events(project_id,created_at DESC); CREATE INDEX project_cases_case_idx ON public.project_cases(case_id);